-- Vorbefüllte, globale Übungen (user_id = NULL). Fotos: Free Exercise DB (Public Domain); die App nutzt mitgelieferte, umgefärbte Versionen.
on conflict (id) do update set name = excluded.name, muscle_group = excluded.muscle_group, equipment = excluded.equipment, image_url = excluded.image_url, bodyweight = excluded.bodyweight;
